"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass, replace
from datetime import timedelta, timezone
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError


@dataclass(frozen=True)
class Policy:
    max_size: int | None = None
    max_age: timedelta | None = None
    naming: str = "numbered"
    offset: timezone = timezone.utc
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


_SIZE = re.compile(r"([0-9]+)([KkMmGg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_WHOLE = re.compile(r"[0-9]+\Z")
_UNITS = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}
_SPANS = {"m": timedelta(minutes=1), "h": timedelta(hours=1), "d": timedelta(days=1)}


def _fail(message):
    raise DataError("policy", f"policy.ini: {message}")


def _size(value):
    if value == "off":
        return None
    match = _SIZE.match(value)
    if not match:
        _fail(f"bad size {value!r}")
    return int(match.group(1)) * _UNITS[match.group(2).lower()]


def _duration(value):
    if value == "off":
        return None
    match = _DURATION.match(value)
    if not match:
        _fail(f"bad duration {value!r}")
    return int(match.group(1)) * _SPANS[match.group(2)]


def _naming(value):
    if value not in ("numbered", "dated"):
        _fail(f"bad naming {value!r}")
    return value


def _offset(value):
    match = _OFFSET.match(value)
    if not match or int(match.group(2)) > 23 or int(match.group(3)) > 59:
        _fail(f"bad offset {value!r}")
    span = timedelta(hours=int(match.group(2)), minutes=int(match.group(3)))
    return timezone(-span if match.group(1) == "-" else span)


def _whole(minimum):
    def parse(value):
        if not _WHOLE.match(value) or int(value) < minimum:
            _fail(f"bad number {value!r}")
        return int(value)

    return parse


def _keep_days(value):
    return None if value == "off" else _whole(1)(value)


_PARSERS = {
    "max_size": _size,
    "max_age": _duration,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _whole(0),
    "keep": _whole(1),
    "keep_days": _keep_days,
}


class Rules:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections

    def names(self) -> set:
        return set(self.sections)

    def for_stream(self, name: str) -> Policy:
        merged = {**self.defaults, **self.sections.get(name, {})}
        return replace(Policy(), **merged)


def load(path: Path) -> Rules:
    if not path.exists():
        return Rules({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        _fail(str(e))
    defaults = None
    sections = {}
    current = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _fail(f"bad line {line!r}")
            title = line[1:-1]
            if title == "defaults":
                if defaults is not None:
                    _fail("section defaults twice")
                defaults = current = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    _fail(f"section {name} twice")
                sections[name] = current = {}
            else:
                _fail(f"unknown section {title!r}")
            continue
        if current is None or "=" not in line:
            _fail(f"bad line {line!r}")
        key, value = (part.strip() for part in line.split("=", 1))
        if key not in _PARSERS:
            _fail(f"unknown key {key!r}")
        if key in current:
            _fail(f"key {key} twice")
        current[key] = _PARSERS[key](value)
    return Rules(defaults or {}, sections)
