"""rotate (docs/rotate.md)."""

import gzip
import os
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_STAMP = re.compile(
    r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})\Z"
)
_LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?\Z")
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")


def parse_time(value):
    """A time of data.md section 2 as an aware datetime, or None."""
    if not isinstance(value, str):
        return None
    try:
        if _LEGACY.match(value):
            return datetime.fromisoformat(value).replace(tzinfo=timezone.utc)
        if _STAMP.match(value):
            return datetime.fromisoformat(value)
    except ValueError:
        return None
    return None


class Archive:
    def __init__(self, name, key, compressed, path=None):
        self.name = name
        self.key = key
        self.compressed = compressed
        self.path = path
        self.new = False
        self.old_name = name
        self.time = None
        self.final = name
        self.compress = False


def _archives(ctx, name, naming):
    found = []
    logs = streams.logs_dir(ctx.data)
    prefix = f"{name}.log."
    if not logs.is_dir():
        return found
    for path in logs.iterdir():
        if not path.is_file() or not path.name.startswith(prefix):
            continue
        rest = path.name[len(prefix):]
        if naming == "numbered":
            match = _NUMBERED.match(rest)
            if match:
                found.append(Archive(path.name, (-int(match.group(1)),), bool(match.group(2)), path))
                found[-1].place = (int(match.group(1)),)
        else:
            match = _DATED.match(rest)
            if match:
                try:
                    day = date.fromisoformat(match.group(1))
                except ValueError:
                    continue
                count = int(match.group(2) or 1)
                found.append(Archive(path.name, (day, count), bool(match.group(3)), path))
                found[-1].place = (day, count)
    seen = set()
    for item in found:
        if item.place in seen:
            raise DataError("archives", f"{name}: two archives in the same place")
        seen.add(item.place)
    found.sort(key=lambda item: item.key, reverse=True)
    return found


def _validate_state(doc, existing):
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue

        def bad(what):
            raise DataError("state", f"state.json: {name}: {what}")

        if "opened" in entry and parse_time(entry["opened"]) is None:
            bad("opened")
        if "archives" in entry:
            if not isinstance(entry["archives"], dict):
                bad("archives")
            for value in entry["archives"].values():
                if parse_time(value) is None:
                    bad("archive time")
        if "rotations" in entry:
            value = entry["rotations"]
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                bad("rotations")


def _first_line_time(path):
    with path.open("rb") as f:
        line = f.readline()
    text = line.decode("utf-8", errors="replace").rstrip("\r\n")
    return parse_time(text.split(" ", 1)[0])


def _reason(ctx, pol, name, entry, force):
    log = streams.log_path(ctx.data, name)
    if not log.is_file():
        return "no log"
    size = log.stat().st_size
    if size == 0:
        return "empty"
    if force:
        return "forced"
    if pol.max_size is not None and size >= pol.max_size:
        return "size"
    if pol.max_age is not None:
        opened = parse_time(entry["opened"]) if "opened" in entry else _first_line_time(log)
        if opened is not None and ctx.now - opened >= pol.max_age:
            return "age"
    return "not due"


def _plan(ctx, name, pol, entry, force):
    reason = _reason(ctx, pol, name, entry, force)
    items = _archives(ctx, name, pol.naming)
    times = entry.get("archives", {})
    for item in items:
        item.time = times.get(item.name)
    rotated = reason in ("forced", "size", "age")
    if rotated:
        if pol.naming == "numbered":
            fresh = Archive(f"{name}.log.1", (1 << 62,), False)
        else:
            day = ctx.now.astimezone(pol.offset).date()
            counts = [item.key[1] for item in items if item.key[0] == day]
            suffix = day.isoformat() + (f".{max(counts) + 1}" if counts else "")
            fresh = Archive(f"{name}.log.{suffix}", (day, max(counts) + 1 if counts else 1), False)
        fresh.new = True
        fresh.old_name = None
        fresh.time = ctx.stamp
        items.append(fresh)
        items.sort(key=lambda item: item.key, reverse=True)
    kept, removed = [], []
    for position, item in enumerate(items, 1):
        gone = position > pol.keep
        if not gone and pol.keep_days is not None and item.time is not None:
            when = ctx.now if item.new else parse_time(item.time)
            gone = ctx.now - when >= timedelta(days=pol.keep_days)
        (removed if gone else kept).append(item)
    for position, item in enumerate(kept, 1):
        base = f"{name}.log."
        item.compress = not item.compressed and position > pol.compress_after
        if pol.naming == "numbered":
            plain = f"{base}{position}"
        else:
            plain = item.name[:-3] if item.compressed else item.name
        item.final = plain + (".gz" if item.compressed or item.compress else "")
    return reason, rotated, kept, removed


def _lines(name, reason, rotated, kept, removed):
    out = [f"{name}: " + (f"rotate ({reason})" if rotated else reason)]
    for item in kept:
        if item.new:
            out.append(f"  new {item.final}")
        elif item.final != item.name:
            out.append(f"  {item.final} <- {item.name}")
        else:
            out.append(f"  {item.name}")
    for item in removed:
        out.append(f"  remove {item.name}")
    return out


def _apply(ctx, name, rotated, kept, removed):
    logs = streams.logs_dir(ctx.data)
    active = streams.log_path(ctx.data, name)
    pending = []
    for index, item in enumerate(kept):
        if item.new:
            source = active
        elif item.final != item.name:
            source = item.path
        else:
            continue
        temp = logs / f".logkeep-tmp-{name}-{index}"
        os.rename(source, temp)
        pending.append((item, temp))
    for item in removed:
        if item.path is not None:
            item.path.unlink()
    if rotated:
        active.write_bytes(b"")
    for item, temp in pending:
        target = logs / item.final
        if item.compress:
            target.write_bytes(gzip.compress(temp.read_bytes(), mtime=0))
            temp.unlink()
        else:
            os.rename(temp, target)


def run(ctx, args):
    rules = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | rules.names()
    _validate_state(doc, existing)
    wanted = sorted(set(args.streams)) if args.streams else sorted(existing)
    for name in wanted:
        if name not in existing:
            raise Refused("unknown-stream", f"no stream {name}")
    plans = []
    for name in wanted:
        pol = rules.for_stream(name)
        entry = doc["streams"].get(name, {})
        plans.append((name, entry, _plan(ctx, name, pol, entry, args.force)))
    out = []
    rotated_count = removed_count = compressed_count = 0
    for name, entry, (reason, rotated, kept, removed) in plans:
        out.extend(_lines(name, reason, rotated, kept, removed))
        rotated_count += rotated
        removed_count += len(removed)
        compressed_count += sum(item.compress for item in kept)
    out.append(f"{rotated_count} rotated, {removed_count} removed, {compressed_count} compressed")
    if args.dry_run:
        out.append("dry run: nothing written")
        return out
    for name, entry, (reason, rotated, kept, removed) in plans:
        _apply(ctx, name, rotated, kept, removed)
        new_entry = {}
        if rotated:
            new_entry["opened"] = ctx.stamp
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        new_entry["archives"] = {item.final: item.time for item in kept if item.time is not None}
        doc["streams"][name] = new_entry
    ctx.data.mkdir(parents=True, exist_ok=True)
    state.save(ctx.state_path, doc)
    return out
