def _lines(name, reason, rotated, kept, removed):
    out = [f"{name}: " + (f"rotate ({reason})" if rotated else reason)]
    for item in kept:
        if item.new:
            out.append(f"  new {item.final}")
        elif item.final != item.name:
            out.append(f"  {item.final} <- {item.name}")
        else:
            out.append(f"  {item.name}")
    for item in removed:
        out.append(f"  remove {item.name}")
    return out


def _apply(ctx, name, rotated, kept, removed):
    logs = streams.logs_dir(ctx.data)
    active = streams.log_path(ctx.data, name)
    pending = []
    for index, item in enumerate(kept):
        if item.new:
            source = active
        elif item.final != item.name:
            source = item.path
        else:
            continue
        temp = logs / f".logkeep-tmp-{name}-{index}"
        os.rename(source, temp)
        pending.append((item, temp))
    for item in removed:
        if item.path is not None:
            item.path.unlink()
    if rotated:
        active.write_bytes(b"")
    for item, temp in pending:
        target = logs / item.final
        if item.compress:
            target.write_bytes(gzip.compress(temp.read_bytes(), mtime=0))
            temp.unlink()
        else:
            os.rename(temp, target)


def run(ctx, args):
    rules = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | rules.names()
    _validate_state(doc, existing)
    wanted = sorted(set(args.streams)) if args.streams else sorted(existing)
    for name in wanted:
        if name not in existing:
            raise Refused("unknown-stream", f"no stream {name}")
    plans = []
    for name in wanted:
        pol = rules.for_stream(name)
        entry = doc["streams"].get(name, {})
        plans.append((name, entry, _plan(ctx, name, pol, entry, args.force)))
    out = []
    rotated_count = removed_count = compressed_count = 0
    for name, entry, (reason, rotated, kept, removed) in plans:
        out.extend(_lines(name, reason, rotated, kept, removed))
        rotated_count += rotated
        removed_count += len(removed)
        compressed_count += sum(item.compress for item in kept)
    out.append(f"{rotated_count} rotated, {removed_count} removed, {compressed_count} compressed")
    if args.dry_run:
        out.append("dry run: nothing written")
        return out
    for name, entry, (reason, rotated, kept, removed) in plans:
        _apply(ctx, name, rotated, kept, removed)
        new_entry = {}
        if rotated:
            new_entry["opened"] = ctx.stamp
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        new_entry["archives"] = {item.final: item.time for item in kept if item.time is not None}
        doc["streams"][name] = new_entry
    ctx.data.mkdir(parents=True, exist_ok=True)
    state.save(ctx.state_path, doc)
    return out
